#include <linux/key.h>
#include <linux/errno.h>
#include <linux/cred.h>

int construct_dest_keyring(struct key **_dest_keyring) {
    struct key *dest_keyring = *_dest_keyring;
    struct key *default_keyring = NULL;
    int ret;

    if (!dest_keyring) {
        struct cred *cred = current_cred();
        default_keyring = find_default_keyring(cred->uid, cred->gid);
        if (IS_ERR(default_keyring)) {
            return PTR_ERR(default_keyring);
        }
        dest_keyring = default_keyring;
    }

    ret = key_validate(dest_keyring);
    if (ret < 0) {
        return ret;
    }

    *_dest_keyring = dest_keyring;
    return 0;
}

