    ret = key_permission(dest_keyring, KEY_NEED_READ | KEY_NEED_WRITE);
    if (ret < 0) {
        key_put(dest_keyring);
        return ret;
    }

    /* Update the provided pointer with the determined keyring */
    *_dest_keyring = dest_keyring;

    return 0;
}

